head.script:
$(document).ready(function(){

        $('.facebook-popup').click(function(event) { 

            $(this).toggleClass('active').siblings().removeClass('active');
            var url_video = $('.facebook-popup.active iframe').attr('src'); //récupération de l'url de la vidéo sur laquelle on a cliqué

            $('#facebook_popup .video iframe').attr('src', url_video); //Passage de l'url à l'iframe de la fenêtre popup

            $('#facebook_popup').toggleClass('active'); //Affichade la fenêtre popup
        });

        $('#facebook_popup').click(function(event) {
            $('#facebook_popup .video iframe').attr('src', '');
            $('#facebook_popup').removeClass('active');
        });
    });

$(document).ready(function(){

    //Script du flash

    var owl_flash = $('#owl_flash');

    owl_flash.owlCarousel({
        loop:true,
        nav:false,
        dots:false,
        autoplay: 5,
        autoplayHoverPause: true,
        responsive:{
            0:{
                items:1
            },
            600:{
                items:1
            },
            1000:{
                items:1
            },

            1200:{
                items:1
            }
        }
    })
})

