link.script:
(function(d, s, id) {
        var js, fjs = d.getElementsByTagName(s)[0];
        if (d.getElementById(id)) return;
        js = d.createElement(s);
        js.id = id;
        js.src = "//connect.facebook.net/fr_FR/sdk.js#xfbml=1&version=v2.5&appId=220779081335178";
        fjs.parentNode.insertBefore(js, fjs);
    }
    (document, 'script', 'facebook-jssdk')
);

$(function() {
    $('#newsletterForm').on('submit', function(event) {
        var v = grecaptcha.getResponse();
        if (v.length == 0) {
            $('#newsletterForm #captcha-message').html("Veuillez valider le ReCaptcha SVP !");
            event.preventDefault();
            event.stopPropagation();
            // Arrêt d'envoi du formulaire
        }
    });

});

document.addEventListener('DOMContentLoaded', () => {
    const wrapper = document.getElementById('flashWrapper');
    const itemHeight = 135; // 125px height + 10px margin-bottom
    const visible = 3;
    const scrollSpeed = 3000;

    let index = 0;
    const originalItems = Array.from(wrapper.children);
    const totalOriginal = originalItems.length;

    // Clonage pour effet infini
    originalItems.forEach(item => {
        const clone = item.cloneNode(true);
        wrapper.appendChild(clone);
    });

    const allItems = wrapper.children;

    function updateActiveClass() {
        // Supprimer toutes les classes "active"
        Array.from(allItems).forEach(el => el.classList.remove('active'));

        // Ajouter la classe active à l'élément actuellement en haut
        const current = allItems[index];
        if (current) {
            current.classList.add('active');
        }
    }

    function scroll() {
        index++;
        wrapper.style.transition = 'transform 1s ease-in-out';
        wrapper.style.transform = `translateY(-${index * itemHeight}px)`;

        updateActiveClass();

        if (index >= totalOriginal) {
            setTimeout(() => {
                wrapper.style.transition = 'none';
                wrapper.style.transform = 'translateY(0)';
                index = 0;
                updateActiveClass(); // reset la bonne classe active aussi
            }, 1000);
        }
    }

    updateActiveClass(); // Initiale
    setInterval(scroll, scrollSpeed);
});

div.script:
$(document).ready(function() {
    $('#siteSelect').select2({
        placeholder: 'Sites des ministères',
        minimumInputLength: 0,
        ajax: {
            url: 'https://www.sante.gouv.ci/ajax/search/ministeres',
            dataType: 'json',
            delay: 250,
            data: function(params) {
                return {
                    q: params.term || ''
                };
            },
            processResults: function(data) {
                return {
                    results: data
                };
            },
            cache: true
        },
        language: {
            errorLoading: () => "Impossible de charger les résultats.",
            inputTooShort: () => "Tapez au moins un caractère.",
            noResults: () => "Aucun résultat trouvé.",
            searching: () => "Recherche en cours..."
        }
    });

    // Forcer le chargement initial à l’ouverture
    $('#siteSelect').on('select2:open', function() {
        $('.select2-search__field').trigger('input');
    });
});

